// Transportation network simplex.
// Returns 0 on optimal. G is the transport plan.
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <vector>
#include <limits>
#include <cstdio>

extern "C" int solve_emd(int n, const double* a, const double* b, const double* M, double* G) {
    const int N = 2 * n;
    const int S = n; // sink offset

    std::vector<int> parent(N, -1);
    std::vector<int> depth(N, 0);
    std::vector<double> pot(N, 0.0);
    std::vector<double> flow(N, 0.0); // nonnegative flow source->sink on edge (node, parent[node])
    std::vector<int> child_head(N, -1);
    std::vector<int> child_next(N, -1); // sibling linked list, indexed by child node
    std::vector<int> nchild(N, 0);

    auto rebuild_children = [&]() {
        std::fill(child_head.begin(), child_head.end(), -1);
        std::fill(nchild.begin(), nchild.end(), 0);
        for (int v = 1; v < N; ++v) {
            int p = parent[v];
            child_next[v] = child_head[p];
            child_head[p] = v;
            nchild[p]++;
        }
    };

    auto recompute_depth_pot = [&]() -> int {
        // iterative stack DFS/BFS from root 0
        std::vector<int> st;
        st.push_back(0);
        depth[0] = 0;
        pot[0] = 0.0;
        std::vector<char> seen(N, 0);
        seen[0] = 1;
        int seen_count = 1;
        while (!st.empty()) {
            int u = st.back();
            st.pop_back();
            for (int c = child_head[u]; c != -1; c = child_next[c]) {
                depth[c] = depth[u] + 1;
                if (u < n && c >= n) {
                    pot[c] = pot[u] - M[u * n + (c - S)];
                } else if (c < n && u >= n) {
                    pot[c] = pot[u] + M[c * n + (u - S)];
                } else {
                    return -1;
                }
                seen[c] = 1;
                seen_count++;
                st.push_back(c);
            }
        }
        return seen_count == N ? 0 : -2;
    };

    // ---------- Northwest corner initial basis ----------
    std::vector<double> supply(a, a + n);
    std::vector<double> demand(b, b + n);
    // adjacency for tree build
    std::vector<std::vector<std::pair<int, double>>> adj(N);
    int i = 0, j = 0;
    int nbasic = 0;
    const double Z = 1e-12;
    while (i < n && j < n) {
        double f = supply[i] < demand[j] ? supply[i] : demand[j];
        if (f < 0) f = 0;
        int u = i, v = S + j;
        adj[u].push_back({v, f});
        adj[v].push_back({u, f});
        nbasic++;
        supply[i] -= f;
        demand[j] -= f;
        bool row_done = supply[i] <= Z;
        bool col_done = demand[j] <= Z;
        if (i == n - 1 && j == n - 1) break;
        if (row_done && col_done) {
            // degenerate step: move to next column and add a zero basic edge, then next row
            if (j + 1 < n && i + 1 < n) {
                j++;
                // zero edge (i, j)
                adj[i].push_back({S + j, 0.0});
                adj[S + j].push_back({i, 0.0});
                nbasic++;
                i++;
            } else if (i + 1 < n) {
                i++;
            } else {
                j++;
            }
        } else if (row_done) {
            i++;
        } else {
            j++;
        }
    }
    if (nbasic != 2 * n - 1) {
        std::fprintf(stderr, "nbasic=%d expected %d\n", nbasic, 2 * n - 1);
        return 1;
    }

    // Orient tree from root 0
    std::vector<char> seen(N, 0);
    std::vector<int> stack;
    stack.push_back(0);
    seen[0] = 1;
    parent[0] = -1;
    int visited = 1;
    while (!stack.empty()) {
        int u = stack.back();
        stack.pop_back();
        for (auto& pr : adj[u]) {
            int v = pr.first;
            if (seen[v]) continue;
            seen[v] = 1;
            visited++;
            parent[v] = u;
            flow[v] = pr.second;
            stack.push_back(v);
        }
    }
    if (visited != N) {
        std::fprintf(stderr, "tree disconnected visited=%d\n", visited);
        return 2;
    }
    rebuild_children();
    if (recompute_depth_pot() != 0) return 3;

    const double RTOL = 1e-9;
    const int MAX_ITER = 1000000;

    // thread-local scratch for cycle
    std::vector<int> path_u;
    std::vector<int> path_v;
    path_u.reserve(N);
    path_v.reserve(N);

