        // most negative reduced cost
        int bi = -1, bj = -1;
        double best = -RTOL;
        for (int r = 0; r < n; ++r) {
            double pr = pot[r];
            const double* row = M + r * (int64_t)n;
            const double* ps = pot.data() + S;
            for (int c = 0; c < n; ++c) {
                double rc = row[c] - pr + ps[c];
                if (rc < best) {
                    best = rc;
                    bi = r;
                    bj = c;
                }
            }
        }
        if (bi < 0) {
            std::memset(G, 0, sizeof(double) * (size_t)n * (size_t)n);
            for (int v = 1; v < N; ++v) {
                int p = parent[v];
                int src, snk;
                if (v < n) { src = v; snk = p - S; }
                else { src = p; snk = v - S; }
                double f = flow[v];
                if (f < 0) f = 0;
                G[(size_t)src * n + snk] = f;
            }
            // std::fprintf(stderr, "iters=%d\n", iter);
            return 0;
        }

        int u = bi;
        int v = S + bj;
        // paths to LCA
        path_u.clear();
        path_v.clear();
        int uu = u, vv = v;
        while (depth[uu] > depth[vv]) { path_u.push_back(uu); uu = parent[uu]; }
        while (depth[vv] > depth[uu]) { path_v.push_back(vv); vv = parent[vv]; }
        while (uu != vv) {
            path_u.push_back(uu); uu = parent[uu];
            path_v.push_back(vv); vv = parent[vv];
        }

        double delta = std::numeric_limits<double>::infinity();
        int leave = -1;
        // leaving edge: reverse arcs
        for (int node : path_u) {
            if (node >= n) { // reverse
                if (flow[node] < delta) { delta = flow[node]; leave = node; }
            }
        }
        for (int node : path_v) {
            if (node < n) {
                if (flow[node] < delta) { delta = flow[node]; leave = node; }
            }
        }
        if (leave < 0 || !(delta < 1e300)) return 4;
        if (delta < 0) delta = 0;

        for (int node : path_u) {
            if (node >= n) flow[node] -= delta;
            else flow[node] += delta;
        }
        for (int node : path_v) {
            if (node < n) flow[node] -= delta;
            else flow[node] += delta;
        }

        // Is u in leave's subtree?
        bool u_in = false;
        for (int x = u; x != -1; x = parent[x]) {
            if (x == leave) { u_in = true; break; }
        }
        int attach_from = u_in ? u : v;
        int attach_to = u_in ? v : u;

        // Reverse parent pointers from attach_from up through leave.
        int cur = attach_from;
        int new_parent = attach_to;
        double new_flow = delta;
        while (true) {
            int old_parent = parent[cur];
            double old_flow = flow[cur];
            parent[cur] = new_parent;
            flow[cur] = new_flow;
            new_parent = cur;
            new_flow = old_flow;
            if (cur == leave) break;
            cur = old_parent;
        }
        rebuild_children();
        int prc = recompute_depth_pot();
        if (prc != 0) {
            std::fprintf(stderr, "recompute failed iter=%d prc=%d\n", iter, prc);
            return 5;
        }
    }
    std::fprintf(stderr, "max iter %d best would continue\n", iter);
    return 6;
}
ENDFILE
