// Jonker-Volgenant shortest-path assignment, O(n^3).
// Dense cost matrix, row-major, n x n.
// Returns column assigned to each row in col_of_row.
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>

extern "C" int jv_solve(int n, const double* cost, int* col_of_row) {
    const double INF = 1e100;
    // dual variables
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of_col(n, -1); // which row is assigned to this column
    std::vector<int> pred(n);
    std::vector<double> dist(n);
    std::vector<char> seen(n);

    for (int r = 0; r < n; ++r) {
        // shortest path from free row r to a free column in the equality subgraph, Dijkstra
        int sink = -1;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        std::fill(pred.begin(), pred.end(), -1);

        // init distances from row r
        const double* crow = cost + (size_t)r * n;
        double ur = u[r];
        for (int c = 0; c < n; ++c) {
            dist[c] = crow[c] - ur - v[c];
            pred[c] = r;
        }

        while (true) {
            // find unscanned column with minimum distance
            int cmin = -1;
            double dmin = INF;
            for (int c = 0; c < n; ++c) {
                if (!seen[c] && dist[c] < dmin) {
                    dmin = dist[c];
                    cmin = c;
                }
            }
            if (cmin < 0) return 1; // no column
            seen[cmin] = 1;
            if (row_of_col[cmin] < 0) {
                sink = cmin;
                break;
            }
            // scan: relax through the assigned row of cmin
            int rr = row_of_col[cmin];
            const double* rrow = cost + (size_t)rr * n;
            double urr = u[rr];
            double base = dmin; // dist[cmin]
            for (int c = 0; c < n; ++c) {
                if (seen[c]) continue;
                double alt = base + rrow[c] - urr - v[c];
                if (alt < dist[c]) {
                    dist[c] = alt;
                    pred[c] = rr;
                }
            }
        }

        // update duals
        // delta for scanned columns
        double d_sink = dist[sink];
        u[r] += d_sink;
        for (int c = 0; c < n; ++c) {
            if (seen[c]) {
                // column was scanned (including sink? sink is seen). 
                // Standard JV: for scanned cols except we update v and u of assigned rows.
                v[c] -= (d_sink - dist[c]);
                int rr = row_of_col[c];
                if (rr >= 0) u[rr] += (d_sink - dist[c]);
            }
        }
        // The row r dual was increased by d_sink. Assigned rows of scanned columns increased.
        // But sink's row_of_col is -1 so only v[sink] updated. Good.
        // However u[r] += d_sink AND if r got added via a scanned column it might double count — r is free, not assigned. OK.

        // augment along pred
        int c = sink;
        while (c >= 0) {
            int rr = pred[c];
            int prev_c = -1;
            // find which column rr was previously assigned to
            // we need the previous column of rr. Search row_of_col.
            // Better store col_of_row too.
            // We'll reconstruct: the predecessor column is the one currently assigned to rr, except for the starting row.
            int old_c = -1;
            if (rr != r) {
                for (int k = 0; k < n; ++k) {
                    if (row_of_col[k] == rr) { old_c = k; break; }
                }
            }
            row_of_col[c] = rr;
            c = old_c;
            if (rr == r) break;
        }
    }

    for (int c = 0; c < n; ++c) {
        int r = row_of_col[c];
        if (r < 0) return 2;
        col_of_row[r] = c;
    }
    return 0;
}
ENDFILE
