// Faster LAPJV-style solver.
// 1) column reduction initialization (like Jonker-Volgenant)
// 2) shortest augmenting paths with a binary heap
//
// cost: n*n row-major double
// col_of_row: output int32
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <queue>

struct Node {
    double d;
    int c;
    bool operator<(const Node& o) const { return d > o.d; } // min-heap
};

extern "C" int jv_solve(int n, const double* cost, int* col_of_row) {
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of_col(n, -1);
    std::vector<int> col_of_row_v(n, -1);
    std::vector<int> pred_col(n, -1); // predecessor column on the path (for augmentation)
    std::vector<int> pred_row(n, -1);
    std::vector<double> dist(n);
    std::vector<char> scanned(n);
    std::vector<int> free_rows;
    free_rows.reserve(n);

    // ---------- Column reduction ----------
    // For each column, find the minimum reduced cost over rows (u=0 initially) and assign if row free.
    // v[c] = min_r cost[r,c], and assign the argmin row if free; else mark column free later.
    std::vector<int> min_row(n, 0);
    for (int c = 0; c < n; ++c) {
        double best = cost[c]; // row 0
        int br = 0;
        for (int r = 1; r < n; ++r) {
            double val = cost[(size_t)r * n + c];
            if (val < best) { best = val; br = r; }
        }
        v[c] = best;
        min_row[c] = br;
    }
    // Assign unique columns to their min row, scanning columns from the end (JV does this)
    std::vector<char> row_taken(n, 0);
    for (int c = n - 1; c >= 0; --c) {
        int r = min_row[c];
        if (!row_taken[r]) {
            row_taken[r] = 1;
            row_of_col[c] = r;
            col_of_row_v[r] = c;
            u[r] = 0.0; // cost - v already 0 at the min
        }
    }
    // Reduction transfer: for unassigned rows, set u[r] = min_c (cost - v)
    for (int r = 0; r < n; ++r) {
        if (col_of_row_v[r] >= 0) continue;
        const double* row = cost + (size_t)r * n;
        double best = INF;
        int bc = -1;
        for (int c = 0; c < n; ++c) {
            double red = row[c] - v[c];
            if (red < best) { best = red; bc = c; }
        }
        u[r] = best;
        // if that column is free, assign
        if (row_of_col[bc] < 0) {
            row_of_col[bc] = r;
            col_of_row_v[r] = bc;
        } else {
            free_rows.push_back(r);
        }
    }

    // Augmenting path for remaining free rows, with heap Dijkstra
    std::priority_queue<Node> heap;

    for (int r0 : free_rows) {
        if (col_of_row_v[r0] >= 0) continue; // got assigned somehow
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(scanned.begin(), scanned.end(), 0);
        std::fill(pred_row.begin(), pred_row.end(), -1);
        while (!heap.empty()) heap.pop();

        const double* crow = cost + (size_t)r0 * n;
        double ur = u[r0];
        for (int c = 0; c < n; ++c) {
            dist[c] = crow[c] - ur - v[c];
            pred_row[c] = r0;
            heap.push({dist[c], c});
        }

        int sink = -1;
        while (!heap.empty()) {
            Node cur = heap.top();
            heap.pop();
            int cmin = cur.c;
            if (scanned[cmin]) continue;
            if (cur.d != dist[cmin]) continue;
            scanned[cmin] = 1;
            if (row_of_col[cmin] < 0) {
                sink = cmin;
                break;
            }
            int rr = row_of_col[cmin];
            const double* rrow = cost + (size_t)rr * n;
            double urr = u[rr];
            double base = dist[cmin];
            for (int c = 0; c < n; ++c) {
                if (scanned[c]) continue;
                double alt = base + rrow[c] - urr - v[c];
                if (alt < dist[c]) {
                    dist[c] = alt;
                    pred_row[c] = rr;
                    heap.push({alt, c});
                }
            }
        }
        if (sink < 0) return 1;

        double d_sink = dist[sink];
        // update duals for scanned columns
        for (int c = 0; c < n; ++c) {
            if (!scanned[c]) continue;
            double delta = d_sink - dist[c];
            v[c] -= delta;
            int rr = row_of_col[c];
            if (rr >= 0) u[rr] += delta;
        }
        u[r0] += d_sink;

        // augment
        int c = sink;
        int rr = pred_row[c];
        while (true) {
            row_of_col[c] = rr;
            int old_c = col_of_row_v[rr];
            col_of_row_v[rr] = c;
            if (rr == r0) break;
            c = old_c;
            rr = pred_row[c];
        }
    }

    for (int r = 0; r < n; ++r) {
        if (col_of_row_v[r] < 0) return 2;
        col_of_row[r] = col_of_row_v[r];
    }
    return 0;
}
ENDFILE
