// Epsilon-scaling auction for the assignment problem.
// Optional candidate lists: if cand != nullptr, each row only bids among cand_k columns
// (cand is n * cand_k, row-major int32). A final exact phase can be requested separately.
//
// Returns 0 on success (a perfect matching, optimal within the candidate subgraph
// up to eps).
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cmath>

extern "C" int auction(
    int n,
    const double* cost,   // n*n row-major, used if cand == nullptr
    const int* cand,      // n * cand_k or nullptr
    const double* cand_cost, // n * cand_k reduced? raw costs aligned with cand, or nullptr to index cost
    int cand_k,
    int* col_of_row,
    double eps_final
) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assign(n, -1);
    std::vector<int> unassigned(n);
    std::vector<int> bid_col(n);
    std::vector<double> bid_price(n);

    double cmax = 0.0;
    if (cand) {
        for (int i = 0; i < n * cand_k; ++i) {
            double v = cand_cost ? cand_cost[i] : cost[i];
            if (v > cmax) cmax = v;
        }
    } else {
        // sample
        for (int r = 0; r < n; r += std::max(1, n / 32)) {
            const double* row = cost + (size_t)r * n;
            for (int c = 0; c < n; c += std::max(1, n / 32)) if (row[c] > cmax) cmax = row[c];
        }
        if (cmax <= 0) cmax = 1.0;
    }
    double eps = std::max(eps_final, cmax / 4.0);

    auto phase = [&](double eps) -> bool {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int guard = 0;
        const int GUARD_MAX = std::max(1000000, n * cand_k * 50);
        while (nfree > 0) {
            if (++guard > GUARD_MAX) return false;
            // each free row bids once (Gauss-Seidel: immediate update is usually faster,
            // but Jacobi-style parallel bidding also works). Use Gauss-Seidel for fewer bids.
            int r = unassigned[--nfree];
            int best = -1;
            double best_val = -1e300;
            double second_val = -1e300;
            if (cand) {
                const int* cr = cand + (size_t)r * cand_k;
                const double* cc = cand_cost + (size_t)r * cand_k;
                for (int t = 0; t < cand_k; ++t) {
                    int c = cr[t];
                    double val = -cc[t] - price[c];
                    if (val > best_val) {
                        second_val = best_val;
                        best_val = val;
                        best = c;
                    } else if (val > second_val) {
                        second_val = val;
                    }
                }
                // new price from benefit formulation
                // b = -cc, but we need -cost of best. Find cost of best.
                double cost_best = 0;
                for (int t = 0; t < cand_k; ++t) if (cr[t] == best) { cost_best = cc[t]; break; }
                double new_price = -cost_best - second_val + eps;
                int prev = owner[best];
                owner[best] = r;
                assign[r] = best;
                price[best] = new_price;
                if (prev >= 0) {
                    assign[prev] = -1;
                    unassigned[nfree++] = prev;
                }
            } else {
                const double* row = cost + (size_t)r * n;
                for (int c = 0; c < n; ++c) {
                    double val = -row[c] - price[c];
                    if (val > best_val) {
                        second_val = best_val;
                        best_val = val;
                        best = c;
                    } else if (val > second_val) {
                        second_val = val;
                    }
                }
                double new_price = -row[best] - second_val + eps;
                int prev = owner[best];
                owner[best] = r;
                assign[r] = best;
                price[best] = new_price;
                if (prev >= 0) {
                    assign[prev] = -1;
                    unassigned[nfree++] = prev;
                }
            }
        }
        return true;
    };

    int phases = 0;
    while (true) {
        if (!phase(eps)) return 1;
        ++phases;
        if (eps <= eps_final * 1.0000001) break;
        double next = eps * 0.2;
        if (next < eps_final) next = eps_final;
        eps = next;
        if (phases > 40) return 3;
    }
    for (int r = 0; r < n; ++r) {
        if (assign[r] < 0) return 2;
        col_of_row[r] = assign[r];
    }
    return 0;
}
