// Epsilon-scaling auction. Returns assignment and column prices.
// If cand != nullptr, bids are restricted to cand_k candidates per row.
// cand_cost aligned with cand.
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cmath>

extern "C" int auction(
    int n,
    const double* cost,
    const int* cand,
    const double* cand_cost,
    int cand_k,
    int* col_of_row,
    double* price_out,     // length n, may be nullptr
    double eps_final
) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assign(n, -1);
    std::vector<int> unassigned(n);

    double cmax = 1.0;
    if (cand) {
        cmax = 0.0;
        int N = n * cand_k;
        for (int i = 0; i < N; ++i) {
            double v = cand_cost[i];
            if (v > cmax) cmax = v;
        }
        if (cmax < 1e-12) cmax = 1.0;
    } else {
        cmax = 0.0;
        int step = std::max(1, n / 40);
        for (int r = 0; r < n; r += step) {
            const double* row = cost + (size_t)r * n;
            for (int c = 0; c < n; c += step) if (row[c] > cmax) cmax = row[c];
        }
        if (cmax < 1e-12) cmax = 1.0;
    }
    double eps = std::max(eps_final, cmax * 0.25);

    auto phase = [&](double eps) -> bool {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        long long guard = 0;
        long long GUARD_MAX = (long long)n * (cand ? cand_k : n) * 30LL;
        if (GUARD_MAX < 1000000) GUARD_MAX = 1000000;
        while (nfree > 0) {
            if (++guard > GUARD_MAX) return false;
            int r = unassigned[--nfree];
            int best = -1;
            double best_val = -1e300;
            double second_val = -1e300;
            double cost_best = 0.0;
            if (cand) {
                const int* cr = cand + (size_t)r * cand_k;
                const double* cc = cand_cost + (size_t)r * cand_k;
                for (int t = 0; t < cand_k; ++t) {
                    int c = cr[t];
                    double val = -cc[t] - price[c];
                    if (val > best_val) {
                        second_val = best_val;
                        best_val = val;
                        best = c;
                        cost_best = cc[t];
                    } else if (val > second_val) {
                        second_val = val;
                    }
                }
            } else {
                const double* row = cost + (size_t)r * n;
                for (int c = 0; c < n; ++c) {
                    double val = -row[c] - price[c];
                    if (val > best_val) {
                        second_val = best_val;
                        best_val = val;
                        best = c;
                        cost_best = row[c];
                    } else if (val > second_val) {
                        second_val = val;
                    }
                }
            }
            if (best < 0) return false;
            if (second_val < -1e299) second_val = best_val - 1.0; // only one candidate
            double new_price = -cost_best - second_val + eps;
            // price must not decrease below a sensible value; auction prices are nondecreasing
            // in the benefit formulation if we start from 0 and b<=0... our prices can be negative
            // because b=-cost. That's fine.
            int prev = owner[best];
            owner[best] = r;
            assign[r] = best;
            price[best] = new_price;
            if (prev >= 0 && prev != r) {
                assign[prev] = -1;
                unassigned[nfree++] = prev;
            }
        }
        return true;
    };

    int phases = 0;
    while (true) {
        if (!phase(eps)) return 1;
        if (eps <= eps_final * 1.0000001) break;
        double next = eps * 0.2;
        if (next < eps_final) next = eps_final;
        // warm-start prices into the next phase (don't reset — phase() resets assignment
        // but keeps prices). Good.
        eps = next;
        if (++phases > 50) return 3;
    }
    for (int r = 0; r < n; ++r) {
        if (assign[r] < 0) return 2;
        col_of_row[r] = assign[r];
    }
    if (price_out) {
        std::memcpy(price_out, price.data(), sizeof(double) * n);
    }
    return 0;
}

// Given prices and an assignment, find rows whose globally best column
// (under cost+price) is better than their assigned column by more than tol.
// Writes up to max_out column indices per violating row into extra (n * max_out),
// and sets nextra[r] to the count. Returns number of violating rows.
extern "C" int find_violations(
    int n,
    const double* cost,
    const int* col_of_row,
    const double* price,
    double tol,
    int* extra,      // n * max_out
    int* nextra,     // n
    int max_out
) {
    int nviol = 0;
    for (int r = 0; r < n; ++r) {
        const double* row = cost + (size_t)r * n;
        int assigned = col_of_row[r];
        double assigned_val = -row[assigned] - price[assigned];
        nextra[r] = 0;
        // track top max_out columns that beat assigned_val + tol
        // simple: scan all, keep best max_out that are strictly better
        // We'll collect columns with val > assigned_val + tol, keeping the best max_out.
        // Use a small insertion list.
        int count = 0;
        // first pass: find if any violation exists, and collect top
        // store (val, col) top list
        double top_val[16];
        int top_col[16];
        int K = max_out < 16 ? max_out : 16;
        int filled = 0;
        bool viol = false;
        for (int c = 0; c < n; ++c) {
            double val = -row[c] - price[c];
            if (val > assigned_val + tol) {
                viol = true;
                // insert into top
                if (filled < K) {
                    int p = filled++;
                    while (p > 0 && val > top_val[p - 1]) {
                        top_val[p] = top_val[p - 1];
                        top_col[p] = top_col[p - 1];
                        --p;
                    }
                    top_val[p] = val;
                    top_col[p] = c;
                } else if (val > top_val[K - 1]) {
                    int p = K - 1;
                    while (p > 0 && val > top_val[p - 1]) {
                        top_val[p] = top_val[p - 1];
                        top_col[p] = top_col[p - 1];
                        --p;
                    }
                    top_val[p] = val;
                    top_col[p] = c;
                }
            }
        }
        if (viol) {
            ++nviol;
            nextra[r] = filled;
            int* er = extra + (size_t)r * max_out;
            for (int t = 0; t < filled; ++t) er[t] = top_col[t];
        }
    }
    return nviol;
}
ENDFILE
