// Auction where each row has a candidate list, but if the global best column
// (scanned every bid, or every few bids) is outside the list, it is added.
//
// To hit speed: maintain a dynamic candidate list per row, initially k nearest.
// On each bid, search only candidates. Periodically (or when a phase ends) do a
// global scan to append better columns, then continue.
//
// Simpler design that is still fast:
//   Phase loop with epsilon scaling.
//   Within a phase, rows bid only on their candidate lists (fast).
//   At end of phase, global scan: any row that prefers a column outside its list
//   appends that column. If any were appended, repeat the phase.
//   Final eps is tiny so the result is optimal on the expanded graph, and the
//   global scan certifies no outside column is better — hence globally optimal
//   up to eps.
//
// Candidate storage: each row has up to MAXC candidates. Start with k0.
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <cstdio>

static constexpr int MAXC = 256;

extern "C" int auction_adaptive(
    int n,
    const double* cost,      // n*n
    const int* init_cand,    // n * k0
    const double* init_cost, // n * k0
    int k0,
    int* col_of_row,
    double eps_final
) {
    std::vector<int> cand( (size_t)n * MAXC );
    std::vector<double> cc( (size_t)n * MAXC );
    std::vector<int> krow(n, k0);
    for (int r = 0; r < n; ++r) {
        std::memcpy(&cand[(size_t)r * MAXC], init_cand + (size_t)r * k0, sizeof(int) * k0);
        std::memcpy(&cc[(size_t)r * MAXC], init_cost + (size_t)r * k0, sizeof(double) * k0);
    }

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assign(n, -1);
    std::vector<int> unassigned(n);

    double cmax = 0.0;
    for (int i = 0; i < n * k0; ++i) if (init_cost[i] > cmax) cmax = init_cost[i];
    if (cmax < 1e-12) cmax = 1.0;
    double eps = std::max(eps_final, cmax * 0.25);

    auto phase = [&](double eps) -> bool {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        long long guard = 0;
        long long GUARD_MAX = (long long)n * MAXC * 40LL;
        while (nfree > 0) {
            if (++guard > GUARD_MAX) return false;
            int r = unassigned[--nfree];
            int kr = krow[r];
            const int* cr = &cand[(size_t)r * MAXC];
            const double* ccr = &cc[(size_t)r * MAXC];
            int best = -1;
            double best_val = -1e300, second_val = -1e300, cost_best = 0;
            int best_t = 0;
            for (int t = 0; t < kr; ++t) {
                int c = cr[t];
                double val = -ccr[t] - price[c];
                if (val > best_val) {
                    second_val = best_val;
                    best_val = val;
                    best = c;
                    cost_best = ccr[t];
                    best_t = t;
                } else if (val > second_val) {
                    second_val = val;
                }
            }
            if (best < 0) return false;
            if (second_val < -1e299) second_val = best_val - 1.0;
            double new_price = -cost_best - second_val + eps;
            int prev = owner[best];
            owner[best] = r;
            assign[r] = best;
            price[best] = new_price;
            if (prev >= 0 && prev != r) {
                assign[prev] = -1;
                unassigned[nfree++] = prev;
            }
        }
        return true;
    };

    // expand candidate lists using current prices. returns number of rows expanded.
    auto expand = [&](double tol) -> int {
        int nexp = 0;
        for (int r = 0; r < n; ++r) {
            int kr = krow[r];
            if (kr >= MAXC) continue;
            const double* row = cost + (size_t)r * n;
            int assigned = assign[r];
            double assigned_val = -row[assigned] - price[assigned];
            // find the globally best column
            int best = assigned;
            double best_val = assigned_val;
            for (int c = 0; c < n; ++c) {
                double val = -row[c] - price[c];
                if (val > best_val) { best_val = val; best = c; }
            }
            if (best_val > assigned_val + tol) {
                // add best if not present
                bool present = false;
                const int* cr = &cand[(size_t)r * MAXC];
                for (int t = 0; t < kr; ++t) if (cr[t] == best) { present = true; break; }
                if (!present && kr < MAXC) {
                    cand[(size_t)r * MAXC + kr] = best;
                    cc[(size_t)r * MAXC + kr] = row[best];
                    krow[r] = kr + 1;
                    ++nexp;
                } else if (present) {
                    // already in list but auction didn't pick it — prices/eps issue, count as expansion-needed
                    ++nexp;
                }
            }
        }
        return nexp;
    };

    int outer = 0;
    while (true) {
        if (!phase(eps)) return 1;
        // certify / expand at this eps
        int nexp = expand(eps);  // tolerance ~ eps (auction is eps-optimal)
        int spins = 0;
        while (nexp > 0 && spins < 8) {
            if (!phase(eps)) return 1;
            nexp = expand(eps);
            ++spins;
        }
        if (nexp > 0) {
            // couldn't certify at this eps with MAXC; fall through to smaller eps anyway
        }
        if (eps <= eps_final * 1.0000001) {
            // final strict certify
            int nexp2 = expand(1e-8);
            int spins2 = 0;
            while (nexp2 > 0 && spins2 < 10) {
                if (!phase(eps_final)) return 1;
                nexp2 = expand(1e-8);
                ++spins2;
            }
            if (nexp2 > 0) return 4; // not certified
            break;
        }
        double next = eps * 0.2;
        if (next < eps_final) next = eps_final;
        eps = next;
        if (++outer > 40) return 3;
    }
    for (int r = 0; r < n; ++r) {
        if (assign[r] < 0) return 2;
        col_of_row[r] = assign[r];
    }
    return 0;
}
