// Parallel Jacobi auction + dense scan.
// Each free person computes a bid independently (read-only prices), then we apply
// bids with a conflict rule: for each column, the highest bid wins.
//
// This is the "auction with epsilon scaling" Jacobi variant, which parallelizes
// the O(n^2) scan.
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <thread>
#include <atomic>

struct Bid {
    int row;
    int col;
    double new_price;
    double raise; // how much the price increases (for conflict resolution)
};

extern "C" int auction_par(int n, const double* cost, int* col_of_row, double eps_final, int nthreads) {
    if (nthreads < 1) nthreads = 1;
    if (nthreads > 8) nthreads = 8;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assign(n, -1);

    double cmax = 0.0;
    int step = std::max(1, n / 48);
    for (int r = 0; r < n; r += step) {
        const double* row = cost + (size_t)r * n;
        for (int c = 0; c < n; c += step) if (row[c] > cmax) cmax = row[c];
    }
    if (cmax < 1e-12) cmax = 1.0;
    double eps = std::max(eps_final, cmax * 0.25);

    auto phase = [&](double eps) -> bool {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        std::vector<int> free_rows(n);
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        int nfree = n;
        int guard = 0;
        const int GUARD_MAX = n * 40;

        std::vector<Bid> bids(n);
        while (nfree > 0) {
            if (++guard > GUARD_MAX) return false;
            // parallel bid computation
            int chunk = (nfree + nthreads - 1) / nthreads;
            std::vector<std::thread> threads;
            for (int t = 0; t < nthreads; ++t) {
                int lo = t * chunk;
                int hi = std::min(nfree, lo + chunk);
                if (lo >= hi) break;
                threads.emplace_back([&, lo, hi]() {
                    for (int k = lo; k < hi; ++k) {
                        int r = free_rows[k];
                        const double* row = cost + (size_t)r * n;
                        int best = 0;
                        double best_val = -1e300, second_val = -1e300;
                        for (int c = 0; c < n; ++c) {
                            double val = -row[c] - price[c];
                            if (val > best_val) {
                                second_val = best_val;
                                best_val = val;
                                best = c;
                            } else if (val > second_val) {
                                second_val = val;
                            }
                        }
                        double new_price = -row[best] - second_val + eps;
                        double raise = new_price - price[best];
                        bids[k] = {r, best, new_price, raise};
                    }
                });
            }
            for (auto& th : threads) th.join();

            // resolve conflicts: for each column keep the bid with largest new_price
            // mark which free rows get assigned this round
            std::vector<int> win_bid(n, -1); // col -> index in bids[0..nfree)
            for (int k = 0; k < nfree; ++k) {
                int c = bids[k].col;
                int prev = win_bid[c];
                if (prev < 0 || bids[k].new_price > bids[prev].new_price) {
                    win_bid[c] = k;
                }
            }
            std::vector<char> assigned_now(nfree, 0);
            for (int c = 0; c < n; ++c) {
                int k = win_bid[c];
                if (k < 0) continue;
                int r = bids[k].row;
                int prev_owner = owner[c];
                owner[c] = r;
                assign[r] = c;
                price[c] = bids[k].new_price;
                assigned_now[k] = 1;
                if (prev_owner >= 0 && prev_owner != r) {
                    assign[prev_owner] = -1;
                    // prev_owner becomes free; handled below
                }
            }
            // rebuild free list: rows that didn't win, plus displaced owners
            std::vector<int> new_free;
            new_free.reserve(nfree);
            std::vector<char> is_free(n, 0);
            for (int k = 0; k < nfree; ++k) {
                if (!assigned_now[k]) {
                    int r = bids[k].row;
                    if (!is_free[r]) { is_free[r] = 1; new_free.push_back(r); }
                }
            }
            for (int r = 0; r < n; ++r) {
                if (assign[r] < 0 && !is_free[r]) {
                    is_free[r] = 1;
                    new_free.push_back(r);
                }
            }
            free_rows.swap(new_free);
            nfree = (int)free_rows.size();
        }
        return true;
    };

    int phases = 0;
    while (true) {
        if (!phase(eps)) return 1;
        if (eps <= eps_final * 1.0000001) break;
        double next = eps * 0.25;
        if (next < eps_final) next = eps_final;
        eps = next;
        if (++phases > 40) return 3;
    }
    for (int r = 0; r < n; ++r) {
        if (assign[r] < 0) return 2;
        col_of_row[r] = assign[r];
    }
    return 0;
}
ENDFILE
