{"command":"cat > fast_auction.cpp << 'ENDFILE'
// Fast assignment via epsilon-scaling auction on a dynamic sparse graph,
// with a persistent OpenMP-free thread pool for the certification scan.
//
// Strategy:
// 1. Build k-NN candidate lists (done in Python / here).
// 2. Run Gauss-Seidel auction on candidates (very fast).
// 3. Certify with a parallel full scan. If violations, append those columns and repeat.
//
// Thread pool is process-global so repeated solves don't pay thread startup.
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <cstdio>

static constexpr int MAXC = 320;

struct Pool {
    int nthreads = 0;
    std::vector<std::thread> threads;
    std::mutex mu;
    std::condition_variable cv, cv_done;
    int epoch = 0;
    int done = 0;
    int stop = 0;
    // job
    const double* cost = nullptr;
    const double* price = nullptr;
    const int* assign = nullptr;
    int n = 0;
    double tol = 0;
    int* viol_col = nullptr;   // per row, best violating col or -1
    double* viol_gain = nullptr;
    int* viol_count = nullptr; // atomic-ish, written by threads then summed

    void start(int nt) {
        if (nthreads) return;
        nthreads = nt;
        for (int t = 0; t < nt; ++t) {
            threads.emplace_back([this, t]() { worker(t); });
        }
    }
    void worker(int tid) {
        int seen = 0;
        while (true) {
            std::unique_lock<std::mutex> lk(mu);
            cv.wait(lk, [&]{ return epoch != seen || stop; });
            if (stop) return;
            seen = epoch;
            int n = this->n;
            const double* cost = this->cost;
            const double* price = this->price;
            const int* assign = this->assign;
            double tol = this->tol;
            int* viol_col = this->viol_col;
            double* viol_gain = this->viol_gain;
            lk.unlock();

            int chunk = (n + nthreads - 1) / nthreads;
            int lo = tid * chunk;
            int hi = std::min(n, lo + chunk);
            int local = 0;
            for (int r = lo; r < hi; ++r) {
                const double* row = cost + (size_t)r * n;
                int asg = assign[r];
                double asg_val = -row[asg] - price[asg];
                int best = -1;
                double best_val = asg_val + tol;
                for (int c = 0; c < n; ++c) {
                    double val = -row[c] - price[c];
                    if (val > best_val) { best_val = val; best = c; }
                }
                viol_col[r] = best;
                viol_gain[r] = best >= 0 ? (best_val - asg_val) : 0;
                if (best >= 0) ++local;
            }
            lk.lock();
            // store local in viol_count[tid]
            viol_count[tid] = local;
            if (++done == nthreads) cv_done.notify_one();
        }
    }
    int scan(int n, const double* cost, const double* price, const int* assign,
             double tol, int* viol_col, double* viol_gain) {
        std::vector<int> counts(nthreads);
        {
            std::lock_guard<std::mutex> lk(mu);
            this->n = n;
            this->cost = cost;
            this->price = price;
            this->assign = assign;
            this->tol = tol;
            this->viol_col = viol_col;
            this->viol_gain = viol_gain;
            this->viol_count = counts.data();
            done = 0;
            ++epoch;
        }
        cv.notify_all();
        std::unique_lock<std::mutex> lk(mu);
        cv_done.wait(lk, [&]{ return done == nthreads; });
        int total = 0;
        for (int t = 0; t < nthreads; ++t) total += counts[t];
        return total;
    }
    ~Pool() {
        {
            std::lock_guard<std::mutex> lk(mu);
            stop = 1;
        }
        cv.notify_all();
        for (auto& th : threads) if (th.joinable()) th.join();
    }
};

static Pool g_pool;

extern "C" int auction_fast(
    int n,
    const double* cost,
    const int* init_cand,
    const double* init_ccost,
    int k0,
    int* col_of_row,
    double eps_final,
    int nthreads
) {
    if (nthreads < 1) nthreads = 1;
    g_pool.start(nthreads);

    std::vector<int> cand((size_t)n * MAXC);
    std::vector<double> cc((size_t)n * MAXC);
    std::vector<int> krow(n, k0);
    for (int r = 0; r < n; ++r) {
        std::memcpy(&cand[(size_t)r * MAXC], init_cand + (size_t)r * k0, sizeof(int)*k0);
        std::memcpy(&cc[(size_t)r * MAXC], init_ccost + (size_t)r * k0, sizeof(double)*k0);
    }
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assign(n, -1);
    std::vector<int> unassigned(n);
    std::vector<int> viol_col(n);
    std::vector<double> viol_gain(n);

    double cmax = 0;
    for (int i = 0; i < n * k0; ++i) if (init_ccost[i] > cmax) cmax = init_ccost[i];
    if (cmax < 1e-12) cmax = 1.0;
    double eps = std::max(eps_final, cmax * 0.25);

    auto phase = [&](double eps) -> bool {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        long long guard = 0;
        long long GUARD_MAX = (long long)n * MAXC * 50LL;
        while (nfree > 0) {
            if (++guard > GUARD_MAX) return false;
            int r = unassigned[--nfree];
            int kr = krow[r];
            const int* cr = &cand[(size_t)r * MAXC];
            const double* ccr = &cc[(size_t)r * MAXC];
            int best = -1;
            double best_val = -1e300, second_val = -1e300, cost_best = 0;
            for (int t = 0; t < kr; ++t) {
                double val = -ccr[t] - price[cr[t]];
                if (val > best_val) {
                    second_val = best_val;
                    best_val = val;
                    best = cr[t];
                    cost_best = ccr[t];
                } else if (val > second_val) {
                    second_val = val;
                }
            }
            if (best < 0) return false;
            if (second_val < -1e299) second_val = best_val - 1.0;
            double new_price = -cost_best - second_val + eps;
            int prev = owner[best];
            owner[best] = r;
            assign[r] = best;
            price[best] = new_price;
            if (prev >= 0 && prev != r) {
                assign[prev] = -1;
                unassigned[nfree++] = prev;
            }
        }
        return true;
    };

    auto expand_from_scan = [&](double tol) -> int {
        int nv = g_pool.scan(n, cost, price.data(), assign.data(), tol, viol_col.data(), viol_gain.data());
        if (nv == 0) return 0;
        int added = 0;
        for (int r = 0; r < n; ++r) {
            int c = viol_col[r];
            if (c < 0) continue;
            int kr = krow[r];
            bool present = false;
            int* cr = &cand[(size_t)r * MAXC];
            for (int t = 0; t < kr; ++t) if (cr[t] == c) { present = true; break; }
            if (!present && kr < MAXC) {
                cr[kr] = c;
                cc[(size_t)r * MAXC + kr] = cost[(size_t)r * n + c];
                krow[r] = kr + 1;
                ++added;
            }
        }
        return nv;
    };

    int outer = 0;
    while (true) {
        if (!phase(eps)) return 1;
        // expand a few times at this eps using parallel scan
        for (int s = 0; s < 6; ++s) {
            int nv = expand_from_scan(std::max(eps, 1e-9));
            if (nv == 0) break;
            if (!phase(eps)) return 1;
        }
        if (eps <= eps_final * 1.0000001) {
            int nv = expand_from_scan(1e-8);
            int spins = 0;
            while (nv > 0 && spins < 12) {
                if (!phase(eps_final)) return 1;
                nv = expand_from_scan(1e-8);
                ++spins;
            }
            if (nv > 0) return 4;
            break;
        }
        double next = eps * 0.2;
        if (next < eps_final) next = eps_final;
        eps = next;
        if (++outer > 30) return 3;
    }
    for (int r = 0; r < n; ++r) {
        if (assign[r] < 0) return 2;
        col_of_row[r] = assign[r];
    }
    return 0;
}
ENDFILE
