        // Reparent.
        auto in_subtree = [&](int x, int sub) {
            while (x != -1) {
                if (x == sub) return true;
                x = parent[x];
            }
            return false;
        };
        bool u_in = in_subtree(u, leave);
        int from = u_in ? u : v;
        int to = u_in ? v : u;
        // new flow_down on the edge once `from` is child of `to`:
        // if from is source and to is sink: flow_down = parent->child = sink->source = -delta
        // if from is sink and to is source: flow_down = source->sink = delta
