        while (true) {
            int old_p = parent[cur];
            double old_f = flow[cur];
            parent[cur] = np;
            flow[cur] = nf;
            // the reversed edge: old parent becomes child, flow_down flips sign
            np = cur;
            nf = -old_f;
            if (cur == leave) break;
            cur = old_p;
            if (cur < 0) return 8;
        }
        rebuild_children();
        int prc = recompute_pot_depth();
        if (prc != 0) {
            std::fprintf(stderr, "pot fail iter %d prc %d\n", iter, prc);
            return 5;
        }
    }
    std::fprintf(stderr, "max iter %d\n", iter);
