// Jonker-Volgenant / successive shortest paths with candidate screening.
// Each row keeps its k cheapest columns. Dijkstra only relaxes those,
// but a column's "screen" (k-th cost - dual) is checked so we rescan a row
// when the screen might hide a better column. This is exact.
//
// For Euclidean costs the screens rarely fail, so each pivot is O(k*n) or less
// with a heap, not O(n^2).
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <queue>
#include <cmath>
#include <cstdio>

struct Node { double d; int c; bool operator<(const Node& o) const { return d > o.d; } };

extern "C" int screened_assign(
    int n,
    const double* cost,
    const int* cand,      // n * k
    const double* ccost,  // n * k
    const double* screen, // n, the k-th smallest cost of the row (threshold)
    int k,
    int* col_of_row
) {
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of_col(n, -1);
    std::vector<int> assign(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::vector<int> touched;
    touched.reserve(n);

    // column reduction init using candidates
    std::vector<char> col_taken(n, 0), row_taken(n, 0);
    // greedy on candidates
    for (int r = 0; r < n; ++r) {
        const int* cr = cand + (size_t)r * k;
        const double* cc = ccost + (size_t)r * k;
        int best = -1; double bv = 1e300;
        for (int t = 0; t < k; ++t) {
            int c = cr[t];
            if (col_taken[c]) continue;
            if (cc[t] < bv) { bv = cc[t]; best = c; }
        }
        if (best >= 0) {
            col_taken[best] = 1;
            row_taken[r] = 1;
            assign[r] = best;
            row_of_col[best] = r;
            u[r] = 0;
            v[best] = bv; // rough
        }
    }
    // dual init: v[c] = min over assigned? set v so reduced costs of candidates >= 0 roughly
    for (int c = 0; c < n; ++c) v[c] = 0;
    for (int r = 0; r < n; ++r) {
        if (assign[r] < 0) continue;
        int c = assign[r];
        // find cost
        const int* cr = cand + (size_t)r * k;
        const double* cc = ccost + (size_t)r * k;
        for (int t = 0; t < k; ++t) if (cr[t] == c) { v[c] = cc[t]; break; }
    }

    std::vector<int> free_rows;
    for (int r = 0; r < n; ++r) if (assign[r] < 0) free_rows.push_back(r);

    auto relax_row = [&](int rr, double base, double* dist, int* pred, std::vector<int>& newly, std::priority_queue<Node>& heap, const char* scanned) {
        double urr = u[rr];
        const int* cr = cand + (size_t)rr * k;
        const double* cc = ccost + (size_t)rr * k;
        // screen check: if screen[rr] - u[rr] - (some v) could beat dist, full scan
        // A column c is hidden if it's not in cand. Its reduced cost >= screen[rr] - u[rr] - v[c].
        // We full-scan if there exists unscanned c with screen - u - v[c] < dist[c] (i.e. might improve).
        // Cheap test: min over unscanned of (screen - u - v[c] - dist[c]) < 0.
