        // than already-scanned distances... this is subtle.
        // Practical: always iterate candidates (O(k)), and if screen - u[rr] - v_max_unscanned < best_unscanned_dist,
        // full scan. Computing v_max is O(n) unless maintained.
        double vmax = -1e300;
