            double urr = u[rr];
            double vmax = -1e300;
            for (int c = 0; c < n; ++c) if (!scanned[c] && v[c] > vmax) vmax = v[c];
            double min_d = 1e300;
            for (int c = 0; c < n; ++c) if (!scanned[c] && dist[c] < min_d) min_d = dist[c];
