                for (int t = 0; t < k; ++t) {
                    int c = cr[t];
                    if (scanned[c]) continue;
                    double alt = base + cc[t] - urr - v[c];
                    if (alt < dist[c]) {
                        dist[c] = alt;
                        pred[c] = rr;
                        heap.push({alt, c});
                    }
                }
            }
        }
        if (sink < 0) {
            std::fprintf(stderr, "no sink full_scans=%d\n", full_scans);
            return 1;
        }
        double d_sink = dist[sink];
        for (int c = 0; c < n; ++c) {
            if (!scanned[c]) continue;
            double delta = d_sink - dist[c];
