        u[r0] += d_sink;
        int c = sink;
        int rr = pred[c];
        while (true) {
            row_of_col[c] = rr;
            int old = assign[rr];
            assign[rr] = c;
            if (rr == r0) break;
            c = old;
            rr = pred[c];
        }
    }
    // std::fprintf(stderr, "full_scans=%d free=%zu\n", full_scans, free_rows.size());
    for (int r = 0; r < n; ++r) {
        if (assign[r] < 0) return 2;
        col_of_row[r] = assign[r];
    }
    return 0;
}
