// Modified LAPJV:
// - column reduction initialization (finds many assignments for Euclidean costs)
// - shortest augmenting paths
// - each row keeps a dynamic shortlist of k best reduced-cost columns, refreshed
//   when the dual moves enough that the shortlist might be stale.
//
// Refresh test: shortlist is valid while v hasn't increased past the threshold
// stored when the shortlist was built. We store for each row the v snapshot
// threshold: a column outside the list had red = cost - u - v_old >= thresh.
// It becomes competitive if v decreased (prices). Since v only decreases for
// scanned columns during augmentation, shortlists go stale often. 
//
// SIMPLER FAST VERSION that is still exact:
// Use the classical JV "column reduction + reduction transfer + augmenting row"
// but implement the inner scan with AVX-ish manual unroll and -O3 -ffast-math,
// and initialize with column reduction so the number of augmentations is small.
//
// Then compare to POT. If augmentations are ~n and each is O(n^2), still slow.
// Column reduction on random costs assigns about n/e rows? For Euclidean, more.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <limits>

extern "C" int jv_count(int n, const double* cost, int* col_of_row, int* n_aug_out) {
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of_col(n, -1), assign(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> seen(n);

    // Column reduction
    std::vector<int> minrow(n);
    for (int c = 0; c < n; ++c) {
        double best = cost[c];
        int br = 0;
        for (int r = 1; r < n; ++r) {
            double val = cost[(size_t)r * n + c];
            if (val < best) { best = val; br = r; }
        }
        v[c] = best;
        minrow[c] = br;
    }
    std::vector<char> row_taken(n, 0);
    int n_assigned = 0;
    for (int c = n - 1; c >= 0; --c) {
        int r = minrow[c];
        if (!row_taken[r]) {
            row_taken[r] = 1;
            row_of_col[c] = r;
            assign[r] = c;
            ++n_assigned;
        }
    }
    // reduction transfer
    std::vector<int> free_rows;
    free_rows.reserve(n - n_assigned);
    for (int r = 0; r < n; ++r) {
        if (assign[r] >= 0) continue;
        const double* row = cost + (size_t)r * n;
        double best = INF, second = INF;
        int bc = -1;
        for (int c = 0; c < n; ++c) {
            double red = row[c] - v[c];
            if (red < best) { second = best; best = red; bc = c; }
            else if (red < second) second = red;
        }
        u[r] = best;
        v[bc] -= (second - best); // transfer? JV transfers the difference to the column if unique min
        // Only transfer if this row's min is unique and column not taken — classic JV is more careful.
        // Skip transfer to keep correctness of later SSP; u[r]=best is a valid init for free rows.
        if (row_of_col[bc] < 0) {
            row_of_col[bc] = r;
            assign[r] = bc;
            ++n_assigned;
        } else {
            free_rows.push_back(r);
        }
    }

    int n_aug = 0;
    for (int r0 : free_rows) {
        if (assign[r0] >= 0) continue;
        ++n_aug;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        const double* crow = cost + (size_t)r0 * n;
        double ur = u[r0];
        for (int c = 0; c < n; ++c) {
            dist[c] = crow[c] - ur - v[c];
            pred[c] = r0;
        }
        int sink = -1;
        while (true) {
            int cmin = -1;
            double dmin = INF;
            for (int c = 0; c < n; ++c) if (!seen[c] && dist[c] < dmin) { dmin = dist[c]; cmin = c; }
            if (cmin < 0) return 1;
            seen[cmin] = 1;
            if (row_of_col[cmin] < 0) { sink = cmin; break; }
            int rr = row_of_col[cmin];
            const double* rrow = cost + (size_t)rr * n;
            double urr = u[rr];
            double base = dmin;
            for (int c = 0; c < n; ++c) {
                if (seen[c]) continue;
                double alt = base + rrow[c] - urr - v[c];
                if (alt < dist[c]) { dist[c] = alt; pred[c] = rr; }
            }
        }
        double d_sink = dist[sink];
        u[r0] += d_sink;
        for (int c = 0; c < n; ++c) if (seen[c]) {
            double delta = d_sink - dist[c];
            v[c] -= delta;
            int rr = row_of_col[c];
            if (rr >= 0) u[rr] += delta;
        }
        int c = sink;
        while (true) {
            int rr = pred[c];
            int old = assign[rr];
            row_of_col[c] = rr;
            assign[rr] = c;
            if (rr == r0) break;
            c = old;
        }
    }
    if (n_aug_out) *n_aug_out = n_aug;
    for (int r = 0; r < n; ++r) col_of_row[r] = assign[r];
    // also report initial assigned via a side channel: store in n_aug_out high? no, print
    std::fprintf(stderr, "n=%d initial_assigned_before_free_loop approx free_started=%zu augs=%d\n", n, free_rows.size(), n_aug);
    return 0;
}
ENDFILE
