            row_of_col[c] = r;
            assign[r] = c;
        }
    }
    std::vector<int> free_rows;
    for (int r = 0; r < n; ++r) {
        if (assign[r] >= 0) continue;
        const double* row = cost + (size_t)r * n;
        double best = INF;
        int bc = -1;
        for (int c = 0; c < n; ++c) {
            double red = row[c] - v[c];
            if (red < best) { best = red; bc = c; }
        }
        u[r] = best;
        if (row_of_col[bc] < 0) {
            row_of_col[bc] = r;
            assign[r] = bc;
        } else free_rows.push_back(r);
