        if (assign[r0] >= 0) continue;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        double ur = u[r0];
        const int* cr = cand + (size_t)r0 * k;
        const double* row0 = cost + (size_t)r0 * n;
        // init distances from candidates, full-scan if screen says so
        bool init_full = false;
