        for (int c = 0; c < n; ++c) {
            dist[c] = screen[r0] - ur - v[c]; // lower bound
            pred[c] = r0;
            exact[c] = 0;
        }
        for (int t = 0; t < k; ++t) {
            int c = cr[t];
            dist[c] = row0[c] - ur - v[c];
            exact[c] = 1;
        }

        int sink = -1;
        // Dijkstra with lazy bound refinement. Use dense scan for min (n=600, fine if few augs
        // and few refinements).
        while (true) {
            int cmin = -1;
            double dmin = INF;
            for (int c = 0; c < n; ++c) if (!seen[c] && dist[c] < dmin) { dmin = dist[c]; cmin = c; }
            if (cmin < 0) return 1;
            if (!exact[cmin]) {
                // refine
                ++n_full;
                double true_d = row0[cmin] - ur - v[cmin];
                exact[cmin] = 1;
                dist[cmin] = true_d;
                if (true_d > dmin + 1e-15) continue; // not actually the min
            }
            seen[cmin] = 1;
            if (row_of_col[cmin] < 0) { sink = cmin; break; }
            int rr = row_of_col[cmin];
            double base = dist[cmin];
            double urr = u[rr];
            const int* crr = cand + (size_t)rr * k;
            const double* rrow = cost + (size_t)rr * n;
            // relax candidates exactly
            for (int t = 0; t < k; ++t) {
                int c = crr[t];
                if (seen[c]) continue;
                double alt = base + rrow[c] - urr - v[c];
                if (alt < dist[c]) {
                    dist[c] = alt;
                    pred[c] = rr;
                    exact[c] = 1;
                }
            }
            // relax non-candidates by lower bound; if bound already worse than dist, skip
            double bound_base = base + screen[rr] - urr;
            for (int c = 0; c < n; ++c) {
                if (seen[c] || exact[c]) continue;
                double alt_lb = bound_base - v[c];
                if (alt_lb < dist[c]) {
                    dist[c] = alt_lb;
                    pred[c] = rr;
                    // exact stays 0; will refine if selected
                }
            }
        }
        double d_sink = dist[sink];
        u[r0] += d_sink;
        for (int c = 0; c < n; ++c) if (seen[c]) {
            double delta = d_sink - dist[c];
            v[c] -= delta;
            int rr = row_of_col[c];
            if (rr >= 0) u[rr] += delta;
        }
        int c = sink;
        while (true) {
            int rr = pred[c];
            int old = assign[rr];
            row_of_col[c] = rr;
            assign[rr] = c;
            if (rr == r0) break;
            c = old;
        }
    }
    if (n_full_out) *n_full_out = n_full;
    for (int r = 0; r < n; ++r) {
        if (assign[r] < 0) return 2;
        col_of_row[r] = assign[r];
    }
    return 0;
}
