// Gauss-Seidel epsilon-scaling auction on a growing candidate list.
// After each phase, one parallel-free full scan appends violating columns.
// Tuned to minimize scans: use a generous initial k and only scan at the final epsilon.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>
#include <cmath>
#include <cstdio>

static constexpr int MAXC = 256;

extern "C" int auction_gs(
    int n,
    const double* cost,
    const int* init_cand,
    const double* init_cc,
    int k0,
    int* col_of_row,
    double eps_final,
    int* nscans_out
) {
    std::vector<int> cand((size_t)n * MAXC);
    std::vector<double> cc((size_t)n * MAXC);
    std::vector<int> krow(n, k0);
    for (int r = 0; r < n; ++r) {
        std::memcpy(&cand[(size_t)r * MAXC], init_cand + (size_t)r * k0, sizeof(int) * k0);
        std::memcpy(&cc[(size_t)r * MAXC], init_cc + (size_t)r * k0, sizeof(double) * k0);
    }
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assign(n, -1);
    std::vector<int> unassigned(n);

    double cmax = 0;
    for (int i = 0; i < n * k0; ++i) if (init_cc[i] > cmax) cmax = init_cc[i];
    if (cmax < 1e-12) cmax = 1.0;
    double eps = std::max(eps_final, cmax * 0.2);

    auto phase = [&](double eps) -> bool {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        long long guard = 0;
        long long GUARD = (long long)n * 80;
        while (nfree) {
            if (++guard > GUARD) return false;
            int r = unassigned[--nfree];
            int kr = krow[r];
            const int* cr = &cand[(size_t)r * MAXC];
            const double* ccr = &cc[(size_t)r * MAXC];
            int best = cr[0];
            double best_val = -ccr[0] - price[best];
            double second_val = -1e300;
            double cost_best = ccr[0];
            for (int t = 1; t < kr; ++t) {
                int c = cr[t];
                double val = -ccr[t] - price[c];
                if (val > best_val) {
                    second_val = best_val;
                    best_val = val;
                    best = c;
                    cost_best = ccr[t];
                } else if (val > second_val) {
                    second_val = val;
                }
            }
            if (second_val < -1e299) second_val = best_val - 1.0;
            double new_price = -cost_best - second_val + eps;
            int prev = owner[best];
            owner[best] = r;
            assign[r] = best;
            price[best] = new_price;
            if (prev >= 0 && prev != r) {
                assign[prev] = -1;
                unassigned[nfree++] = prev;
            }
        }
        return true;
    };

    int nscans = 0;
    auto expand = [&](double tol) -> int {
        ++nscans;
        int added = 0;
        for (int r = 0; r < n; ++r) {
            int kr = krow[r];
            if (kr >= MAXC) continue;
            const double* row = cost + (size_t)r * n;
            int asg = assign[r];
            double asg_val = -row[asg] - price[asg];
            int best = -1;
            double best_val = asg_val + tol;
            // scan, skip if clearly not better. unroll 4
            int c = 0;
            for (; c + 3 < n; c += 4) {
                double v0 = -row[c] - price[c];
                double v1 = -row[c+1] - price[c+1];
                double v2 = -row[c+2] - price[c+2];
                double v3 = -row[c+3] - price[c+3];
                if (v0 > best_val) { best_val = v0; best = c; }
                if (v1 > best_val) { best_val = v1; best = c+1; }
                if (v2 > best_val) { best_val = v2; best = c+2; }
                if (v3 > best_val) { best_val = v3; best = c+3; }
            }
            for (; c < n; ++c) {
                double v = -row[c] - price[c];
                if (v > best_val) { best_val = v; best = c; }
            }
            if (best >= 0) {
                bool present = false;
                int* cr = &cand[(size_t)r * MAXC];
                for (int t = 0; t < kr; ++t) if (cr[t] == best) { present = true; break; }
                if (!present) {
                    cr[kr] = best;
                    cc[(size_t)r * MAXC + kr] = row[best];
                    krow[r] = kr + 1;
                    ++added;
                } else {
                    ++added; // in list but not chosen: eps issue, force another phase
                }
            }
        }
        return added;
    };

    int outer = 0;
    while (true) {
        if (!phase(eps)) return 1;
        if (eps <= eps_final * 1.0000001) {
            int spins = 0;
            int added = expand(1e-9);
            while (added > 0 && spins < 8) {
                if (!phase(eps_final)) return 1;
                added = expand(1e-9);
                ++spins;
            }
            if (added > 0) return 4;
            break;
        }
        eps = std::max(eps_final, eps * 0.15);
        if (++outer > 25) return 3;
    }
    if (nscans_out) *nscans_out = nscans;
    for (int r = 0; r < n; ++r) {
        if (assign[r] < 0) return 2;
        col_of_row[r] = assign[r];
    }
    return 0;
}
ENDFILE
